import{_ as o,o as t,c as n,a0 as r}from"./chunks/framework.CShDTZbC.js";const m=JSON.parse('{"title":"Phase 4A — Production Audit","description":"","frontmatter":{},"headers":[],"relativePath":"phase-4a-production-audit.md","filePath":"phase-4a-production-audit.md"}'),i={name:"phase-4a-production-audit.md"};function a(s,e,c,d,l,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-4a-—-production-audit" tabindex="-1">Phase 4A — Production Audit <a class="header-anchor" href="#phase-4a-—-production-audit" aria-label="Permalink to &quot;Phase 4A — Production Audit&quot;">​</a></h1><h2 id="_1-current-architecture" tabindex="-1">1. Current Architecture <a class="header-anchor" href="#_1-current-architecture" aria-label="Permalink to &quot;1. Current Architecture&quot;">​</a></h2><p>The current codebase (built incrementally through Phases 2 and 3) exists primarily as monolithic, highly coupled experimental scripts (e.g., <code>scratch/phase-3j/runner.mjs</code>).</p><ul><li><strong>Agent Loop</strong>: Hardcoded <code>while(stats.iterations &lt; MAX_ITERATIONS)</code> loop tightly bound to benchmark data structures.</li><li><strong>LLM Integration</strong>: Directly instantiates the <code>openai</code> Node SDK with hardcoded <code>deepseek-chat</code> configuration.</li><li><strong>Sandbox Management</strong>: Uses synchronous <code>child_process.execSync</code> to run bare <code>docker run</code> and <code>docker exec</code> commands.</li><li><strong>Verification</strong>: Verifier logic is tightly coupled to the runner, with hardcoded case IDs (e.g., <code>if (sandboxName === &#39;DEV-03&#39;)</code>).</li><li><strong>Telemetry</strong>: Writes directly to <code>artifacts/phase-3j/summary.json</code> at the end of the script.</li></ul><h2 id="_2-existing-reusable-components" tabindex="-1">2. Existing Reusable Components <a class="header-anchor" href="#_2-existing-reusable-components" aria-label="Permalink to &quot;2. Existing Reusable Components&quot;">​</a></h2><ul><li><strong>System Prompt</strong>: The <code>systemInstruction</code> text has been extensively refined and is production-ready.</li><li><strong>Tool Definitions</strong>: The JSON schemas for <code>read_file</code>, <code>execute_command</code>, and <code>patch_file</code>.</li><li><strong>Patch Logic</strong>: The <code>awk</code> script used to patch files while preserving executable permissions (validated in Phase 3I/3J).</li><li><strong>Output Truncation</strong>: The <code>truncate()</code> function designed to prevent context-window explosion.</li><li><strong>Rate-Limit Handling</strong>: Basic 429 backoff logic.</li></ul><h2 id="_3-components-requiring-refactoring" tabindex="-1">3. Components Requiring Refactoring <a class="header-anchor" href="#_3-components-requiring-refactoring" aria-label="Permalink to &quot;3. Components Requiring Refactoring&quot;">​</a></h2><ul><li><strong>Sandbox Execution</strong>: Replace <code>execSync</code> with asynchronous <code>exec</code> or <code>spawn</code> to prevent blocking the Node.js event loop and to allow real-time UI/CLI feedback.</li><li><strong>Agent Controller</strong>: Decouple the ReAct loop from the benchmark data. The controller must accept a generic <code>Sandbox</code> instance and return a trajectory.</li><li><strong>Dynamic Iteration Control</strong>: Upgrade the hardcoded 15-iteration loop to support early termination upon detecting repeated actions, unrecoverable sandbox states, or verified success.</li><li><strong>Tool Execution Layer</strong>: Move tool logic out of the main loop and into a dedicated <code>src/tools/</code> registry.</li></ul><h2 id="_4-components-requiring-replacement" tabindex="-1">4. Components Requiring Replacement <a class="header-anchor" href="#_4-components-requiring-replacement" aria-label="Permalink to &quot;4. Components Requiring Replacement&quot;">​</a></h2><ul><li><strong>Ad-Hoc Verifier</strong>: Replace hardcoded <code>DEV-03</code> string matching with a generic configuration-driven verifier that can test process exit codes or HTTP health checks independently.</li><li><strong>Credentials Management</strong>: Remove hardcoded provider checks and use generic <code>.env</code> configuration (e.g., <code>LLM_PROVIDER</code>, <code>LLM_MODEL</code>).</li></ul><h2 id="_5-technical-debt" tabindex="-1">5. Technical Debt <a class="header-anchor" href="#_5-technical-debt" aria-label="Permalink to &quot;5. Technical Debt&quot;">​</a></h2><ul><li><strong>Synchronous Blocking</strong>: Extensive use of <code>execSync</code> prevents graceful teardown on process exit (Ctrl+C).</li><li><strong>Test Coupling</strong>: Production code must be fully independent of the 5 benchmark cases used to prove it.</li></ul><h2 id="_6-security-risks" tabindex="-1">6. Security Risks <a class="header-anchor" href="#_6-security-risks" aria-label="Permalink to &quot;6. Security Risks&quot;">​</a></h2><ul><li><strong>Command Injection/Bypass</strong>: The current safety check for <code>execute_command</code> relies on simple string matching (<code>includes(&#39;rm -rf /&#39;)</code>), which is trivial to bypass.</li><li><strong>Sandbox Escapes</strong>: Docker containers are run without resource limits (<code>--memory</code>, <code>--cpus</code>), leaving the host vulnerable to resource starvation (e.g., fork bombs initiated by the agent).</li></ul><h2 id="_7-reliability-risks" tabindex="-1">7. Reliability Risks <a class="header-anchor" href="#_7-reliability-risks" aria-label="Permalink to &quot;7. Reliability Risks&quot;">​</a></h2><ul><li><strong>Network Flakiness</strong>: <code>npm install</code> inside the sandbox can fail randomly. The agent needs clear signals to retry, or the sandbox needs robust network access.</li><li><strong>Long-Running Commands</strong>: An agent might run a server blocking the main thread (like <code>node index.js</code>). The controller must aggressively enforce timeouts on <code>execute_command</code>.</li></ul><h2 id="_8-demo-risks" tabindex="-1">8. Demo Risks <a class="header-anchor" href="#_8-demo-risks" aria-label="Permalink to &quot;8. Demo Risks&quot;">​</a></h2><ul><li>The Demo Mode must instantiate the DEV cases perfectly. If the demo relies on the scratch scripts, it will look like an academic project instead of a real CLI tool.</li></ul><h2 id="_9-missing-production-components" tabindex="-1">9. Missing Production Components <a class="header-anchor" href="#_9-missing-production-components" aria-label="Permalink to &quot;9. Missing Production Components&quot;">​</a></h2><ul><li><strong>CLI Interface</strong>: A user-facing CLI (e.g., <code>bin/devfix</code>) with argument parsing (using <code>commander</code> or <code>yargs</code>) and rich terminal output (spinners, colors).</li><li><strong>Generic Project Loader</strong>: Ability to mount a real local project directory into the sandbox, rather than just executing predefined <code>echo</code> commands.</li><li><strong>Automated Tests</strong>: Unit and integration tests for the controller, tools, and verifier.</li></ul><h2 id="_10-recommended-implementation-order" tabindex="-1">10. Recommended Implementation Order <a class="header-anchor" href="#_10-recommended-implementation-order" aria-label="Permalink to &quot;10. Recommended Implementation Order&quot;">​</a></h2><ol><li><strong>Tool &amp; Sandbox Layer (<code>src/sandbox/</code>, <code>src/tools/</code>)</strong>: Build the asynchronous, resource-limited Docker sandbox and the isolated tool execution functions.</li><li><strong>Verifier Layer (<code>src/verifier/</code>)</strong>: Implement generic Process and HTTP verifiers.</li><li><strong>Agent Controller (<code>src/agent/</code>)</strong>: Implement the LLM API abstraction, context window management, and dynamic iteration loop.</li><li><strong>CLI &amp; Telemetry (<code>src/cli/</code>, <code>src/telemetry/</code>)</strong>: Build the user-facing CLI, rich output formatter, and structured JSON telemetry writer.</li><li><strong>Demo Mode</strong>: Integrate the 5 benchmark cases as a sub-command (<code>devfix demo DEV-04</code>).</li><li><strong>End-to-End Testing</strong>: Validate the final product against the full benchmark.</li></ol>',22)])])}const g=o(i,[["render",a]]);export{m as __pageData,g as default};
